public class SplayTree { static class N{int k;N l,r,p;N(int k){this.k=k;}} N root; void left(N x){N y=x.r;if(y==null)return;x.r=y.l;if(y.l!=null)y.l.p=x;y.p=x.p;if(x.p==null)root=y;else if(x==x.p.l)x.p.l=y;else x.p.r=y;y.l=x;x.p=y;} void right(N x){N y=x.l;if(y==null)return;x.l=y.r;if(y.r!=null)y.r.p=x;y.p=x.p;if(x.p==null)root=y;else if(x==x.p.l)x.p.l=y;else x.p.r=y;y.r=x;x.p=y;} void splay(N x){while(x.p!=null){N p=x.p,g=p.p;if(g==null){if(x==p.l)right(p);else left(p);}else if(x==p.l&&p==g.l){right(g);right(p);}else if(x==p.r&&p==g.r){left(g);left(p);}else if(x==p.r){left(p);right(g);}else{right(p);left(g);}}} public void insert(int k){N z=root,p=null;while(z!=null){p=z;z=k<z.k?z.l:z.r;}z=new N(k);z.p=p;if(p==null)root=z;else if(k<p.k)p.l=z;else p.r=z;splay(z);} public boolean access(int k){N z=root,last=null;while(z!=null){last=z;if(k==z.k){splay(z);return true;}z=k<z.k?z.l:z.r;}if(last!=null)splay(last);return false;} public static void run(){SplayTree t=new SplayTree();for(int x:new int[]{10,20,30,25})t.insert(x);System.out.println("Root after insert-splay="+t.root.k);t.access(10);System.out.println("Root after accessing 10="+t.root.k);System.out.println("Invariant: normal BST order; recent accesses move near root; amortized logarithmic intuition.\n");} public static void main(String[] args){run();}}
